import socket
import threading
import time
from enum import Enum
from struct import calcsize, unpack_from

from six.moves import queue

from .aatrace_message_creator import (
    SICv1_header,
    SICv1_payload_header,
    create_filter_msg,
    hexstr,
)
from .exceptions import (
    CallbackNotRegistered,
    MessageNotTraced,
    ObserverAlreadyRunning,
    ObserverMessageIndexOutOfRange,
)
from .logger_config import log
from .node_creator import create_receiver_nodes, create_sender_node

# SYSCOM msg ids:
AATRACE_MON_CTRL_RESP_MSG = "0x1813"
AATRACE_MON_CTRL_REQ_MSG = "0x1819"
AATRACE_MON_IND_MSG = "0x2991"
AATRACE_AGGREGATED_MON_IND_MSG = "0x0BF9"
AATRACE_AGGREGATED_TIMEOUT_IND_MSG = "0x0C3D"
AATRACE_SUSPEND_TRACING_REQ_MSG = "0x1232"
AATRACE_RESUME_TRACING_REQ_MSG = "0x1233"
AATRACE_SESSION_STATE_CHANGE_NOTIF_MSG = "0x1234"

ENB_ADDRESS = "192.168.255.1"
AATRACE_PORT = 15004
PACKET_SIZE = 16384

QUEUE_TIMEOUT = 0.01
SOCKET_TIMEOUT = 0.01

observer_callbacks = {}


def extract_aatrace_bytes(msg_bytes):
    """to be created"""
    messages = []
    _extract_aatrace(msg_bytes=msg_bytes, offset=0, messages=messages)
    log.info("Extracted {} messages".format(len(messages)))
    return messages


def _extract_aatrace(msg_bytes, offset, messages):
    msg_header = SICv1_header(
        *unpack_from(SICv1_header.format, msg_bytes, offset=offset)
    )
    rest_bytes = msg_bytes[calcsize(SICv1_header.format):]
    if msg_header.message_type_number == AATRACE_MON_IND_MSG:
        payload_header = SICv1_payload_header(
            *unpack_from(SICv1_payload_header.format, rest_bytes, offset=0)
        )
        rest_bytes = rest_bytes[calcsize(SICv1_payload_header.format):]
        aatrace_bytes = rest_bytes[: payload_header.message_length]
        messages.append(aatrace_bytes)
        log.debug("Extracted Aatrace bytes: '{!r}'".format(aatrace_bytes))
        rest_bytes = rest_bytes[payload_header.message_length:]
        if rest_bytes:
            _extract_aatrace(rest_bytes, offset=0, messages=messages)
    else:
        return


def get_string_from_bytes(raw_bytes):
    """to be created"""
    if isinstance(raw_bytes, str):  # in Python2 it is 'str'
        return repr(hexstr(raw_bytes))
    else:
        return raw_bytes.hex()  # in Python3 it is 'bytes'


class AatraceCollector(object):
    """to be created"""

    def __init__(self, aatrace_parser, message_hex_id_list, nodes=None):
        self.aatrace_parser = aatrace_parser
        if not message_hex_id_list:
            raise TypeError("No messages specified to trace.")
        self.sender_node = create_sender_node()
        self.nodes = create_receiver_nodes(nodes)
        self.message_hex_ids = message_hex_id_list
        self.subscribed_observers = {}
        self.is_running = threading.Event()
        self.aatrace_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self._started = threading.Semaphore(0)
        self._start_collector_thread()
        self._started.acquire()

    def start(self):
        """to be created"""
        self._connect_to_trace_service()  # polaczenie do socketa
        self._send_filters_and_wait_for_resposne()
        self.is_running.set()
        self._started.release()
        log.info("Thread started. Entering collector loop.")
        while self.is_running.is_set():
            data = (
                self._receive_data_from_socket()
            )  # nie wspieamy (jeszcze) ze pakiet tcp moze zawierac czesc wiadomosci, a kolejny reszte
            if data and (
                any(
                        observer.is_running.is_set()
                        for observer in self.subscribed_observers.values()
                )
            ):  # ktos slucha
                for raw_aatrace_bytes in extract_aatrace_bytes(data):
                    string_aatrace_bytes = get_string_from_bytes(raw_aatrace_bytes)
                    msg_hex_id = self.aatrace_parser.get_message_hex_id_from_bytes(
                        string_aatrace_bytes
                    )
                    log.info(
                        "Aatrace bytes for msg '{}': '{}'".format(
                            msg_hex_id, string_aatrace_bytes
                        )
                    )
                    if self._is_message_awaited(msg_hex_id):
                        self.subscribed_observers[msg_hex_id].queue.put(
                            string_aatrace_bytes
                        )  # czy moze sie wypisac miedzy if a teraz?
        # self.stop() # czy tutaj tez?
        log.info("Thread finished.")

    def create_observer(
        self,
        msg_hex_id,
        occurrence,
        timeout,
        on_success=None,
        on_timeout=None,
        on_each_occurrence=None,
    ):  # cos zrobic z occurrence
        """to be created"""
        if msg_hex_id not in self.message_hex_ids:
            self.stop()
            raise MessageNotTraced(
                "%s not traced. Filters were sent for %s."
                % (msg_hex_id, self.message_hex_ids)
            )
        if msg_hex_id in self.subscribed_observers.keys():
            if self.subscribed_observers[msg_hex_id].is_running.is_set():
                raise ObserverAlreadyRunning(
                    "Cant create observer for message with hex id: %s" % msg_hex_id
                )

        msg_observer = MessageObserver(
            aatrace_collector=self,
            msg_hex_id=msg_hex_id,
            occurrence=occurrence,
            timeout=timeout,
            on_success=on_success,
            on_timeout=on_timeout,
            on_each_occurrence=on_each_occurrence,
        )
        log.info("Observer for message with hex id '{}' created.".format(msg_hex_id))
        return msg_observer

    def unsubscribe_observer(self, observer):  # moze sie cos nie udac?
        """to be created"""
        del self.subscribed_observers[observer.name]
        log.info("Observer for '{}' unsubscribed.".format(observer.name))

    def subscribe_observer(self, observer):  # moze byc duplikacja - jakis try?
        """to be created"""
        self.subscribed_observers[observer.name] = observer
        log.info("Observer for '{}' subscribed.".format(observer.name))

    def stop(self):
        """to be created"""
        log.info("Stopping collector.")
        self.is_running.clear()
        self._stop_observers()
        self.aatrace_socket.close()

    def _start_collector_thread(self):
        self.thread = threading.Thread(target=self.start)
        self.thread.start()

    def _stop_observers(self):
        for observer in self.subscribed_observers.values():
            observer.stop()
            # self.unsubscribe_observer(observer)  # moze nie kasowac - po co

    def _connect_to_trace_service(self):
        self.aatrace_socket.settimeout(SOCKET_TIMEOUT)
        try:
            self.aatrace_socket.connect((ENB_ADDRESS, AATRACE_PORT))
        except Exception as err:
            self.stop()
            raise err
        else:
            log.info("Connected to socket.")

    def _receive_data_from_socket(self):
        try:
            data = self.aatrace_socket.recv(PACKET_SIZE)
            log.debug("Socket data received: '{!r}'".format(data))
        except socket.timeout:
            return None
        return data

    def _is_message_awaited(self, msg_hex_id):
        return msg_hex_id in self.subscribed_observers.keys()

    def _send_filters_and_wait_for_resposne(self):
        for receiver_node in set(self.nodes.values()):
            filter_msg = create_filter_msg(
                hex_ids=self.message_hex_ids,
                receiver_node=receiver_node,
                sender_node=self.sender_node,
            )
            self.aatrace_socket.send(filter_msg)
            log.debug("Filters sent: '{!r}'".format(filter_msg))
            time.sleep(0.1)
        # czekaj na odpowiedz - trzeba dorobic


class Status(Enum):
    CREATING = 1
    RUNNING = 2
    SUCCESS = 3
    TIMEOUT = 4
    STOPPED = 5


class MessageObserver(object):
    def __init__(
        self,
        aatrace_collector,
        msg_hex_id,
        occurrence,
        timeout,
        on_success,
        on_timeout,
        on_each_occurrence,
    ):
        self.status = Status.CREATING
        self._aatrace_collector = aatrace_collector
        self.on_success = _get_callback(on_success)
        self.on_timeout = _get_callback(on_timeout)
        self.on_each_occurrence = _get_callback(on_each_occurrence)
        self.name = msg_hex_id
        self.occurrence = occurrence
        self.queue = queue.Queue()
        self.is_running = threading.Event()
        self.timeout_timer = threading.Timer(timeout, self._on_timeout)
        self._messages = []
        self._started = threading.Semaphore(0)
        self._aatrace_collector.subscribe_observer(self)
        self._start_observer_thread()
        self._started.acquire()

    def start(self):
        """to be created"""
        self.is_running.set()
        self.status = Status.RUNNING
        self.timeout_timer.start()
        log.info(
            "Observer thread for '{}' started. Entering observer loop".format(self.name)
        )
        self._started.release()
        while self.is_running.is_set():
            try:
                msg_bytes = self.queue.get(timeout=QUEUE_TIMEOUT)
                log.debug("Observer '{}' got bytes: '{}'".format(self.name, msg_bytes))
            except queue.Empty:
                continue
            if self.status != Status.RUNNING:
                self.stop()
                continue
            self._on_each_occurrence(msg_bytes)
            if len(self._messages) == self.occurrence:
                self._on_success()
        log.info(
            "Observer thread for '{}' finished with status: '{}'".format(
                self.name, self.status
            )
        )
        # self._aatrace_collector.unsubscribe_observer(self) # nie trzeba bedzie zastopowany i bedzie mial jakis status

    def stop(self):
        """to be created"""
        if self.status not in [Status.SUCCESS, Status.TIMEOUT]:
            self.status = Status.STOPPED
        self.timeout_timer.cancel()
        self.is_running.clear()
        log.info("Observer for '{}' stopped.".format(self.name))

    def await_finish(self):
        """to be created"""
        log.info("Waiting for Observer for '{}' to finish.".format(self.name))
        self.thread.join()
        self.timeout_timer.join()

    def get_message(self, occurrence=-1):
        """to be created"""
        try:
            return self._messages[occurrence]
        except IndexError:
            raise ObserverMessageIndexOutOfRange(
                "Observer for %s cought only %s messages. Message number %s is out of range"
                % (self.name, len(self._messages), occurrence)
            )

    def _start_observer_thread(self):
        self.thread = threading.Thread(target=self.start)
        self.thread.start()

    def _on_each_occurrence(self, msg_bytes):
        self._messages.append(msg_bytes)
        if self.on_each_occurrence:
            self.on_each_occurrence(msg_bytes)

    def _on_timeout(self):
        log.info("Observer for '{}' status: TIMEOUT".format(self.name))
        self.status = Status.TIMEOUT
        self.stop()
        if self.on_timeout:
            self.on_timeout()

    def _on_success(self):
        log.info("Observer for '{}' status: SUCCESS".format(self.name))
        self.timeout_timer.cancel()
        self.status = Status.SUCCESS
        self.stop()
        if self.on_success:
            self.on_success()


def _get_callback(cb):
    if not cb:
        return None

    if callable(cb):
        observer_callbacks[cb.__name__] = cb
        return cb

    try:
        return observer_callbacks[cb]
    except KeyError:
        raise CallbackNotRegistered(cb)
